dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype*",
      "type": "api list",
      "data point": {
        "type": "api",
        "url": "https://giant.hugeampkpnbi.org/api/bio/keys/c2ct/1?columns=phenotype",
        "data type": "json",
        "data wrapper": [
          "keys"
        ]
      }
    },
    {
      "parameter": "ancestry",
      "label": "Ancestry*",
      "type": "list",
      "values": [
        {
          "label": "Mixed",
          "value": "*"
        },
        {
          "label": "AA",
          "value": "AA"
        },
        {
          "label": "EA",
          "value": "EA"
        },
        {
          "label": "EU",
          "value": "EU"
        },
        {
          "label": "HS",
          "value": "HS"
        },
        {
          "label": "SA",
          "value": "SA"
        }
      ]
    },
    {
      "parameter": "region",
      "label": "Region (chr:start-end or gene)",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true",
      "expand region by": 100000
    },
    {
      "parameter": "csid",
      "label": "CS ID",
      "type": "input"
    }
  ],
  "sections": [
    {
      "section id": "associations",
      "header": "Variants in Credible set region",
      "data point": {
        "type": "bioindex",
        "url": "https://giant.hugeampkpnbi.org/api/bio/",
        "index": "associations",
        "parameters": [
          "phenotype",
          "ancestry",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "display": false,
        "data zoom": {
          "chromosome": "chromosome",
          "position": "Position"
        },
        "initial sort by": {
          "field": "P-Value",
          "type": "number",
          "direction": "desc"
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          },
          {
            "type": "raw",
            "field name": "ref",
            "raw field": "reference"
          },
          {
            "type": "raw",
            "field name": "alt",
            "raw field": "alt"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Standard error",
            "raw field": "stdErr",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Consequence",
            "raw field": "consequence"
          },
          {
            "type": "raw",
            "field name": "Z Score",
            "raw field": "zScore",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "rsID",
            "raw field": "dbSNP"
          },
          {
            "type": "join",
            "field name": "Ref/Alt",
            "fields to join": [
              "reference",
              "alt"
            ],
            "join by": "/"
          },
          {
            "type": "join",
            "field name": "Locus",
            "fields to join": [
              "chromosome",
              "position"
            ],
            "join by": ":"
          },
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "join multi",
            "field name": "KP Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              ":",
              ":"
            ]
          },
          {
            "type": "raw",
            "field name": "chr",
            "raw field": "chromosome"
          },
          {
            "type": "calculate",
            "field name": "-log10(P-Value)",
            "raw field": "pValue",
            "calculation type": "-log10"
          }
        ],
        "top rows": [
          "Variant ID",
          "rsID",
          "Ref/Alt",
          "P-Value",
          "Beta",
          "MAF",
          "Standard error",
          "Z Score",
          "Consequence"
        ],
        "star column": "Variant ID",
        "locus field": "Locus",
        "column formatting": {
          "PPO": {
            "type": [
              "scientific notation"
            ]
          },
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "Odds Ratio": {
            "type": [
              "scientific notation"
            ]
          },
          "Beta": {
            "type": [
              "scientific notation"
            ]
          },
          "EAF": {
            "type": [
              "scientific notation"
            ]
          },
          "MAF": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard error": {
            "type": [
              "scientific notation"
            ]
          },
          "Z Score": {
            "type": [
              "scientific notation"
            ]
          },
          "Target Gene": {
            "type": [
              "link"
            ],
            "link to": "/gene.html?gene=",
            "new tab": "true"
          }
        }
      },
      "filters unused": [
        {
          "field": "Variant ID",
          "label": "Variant ID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "rsID",
          "label": "rsID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "P-Value",
          "label": "P-Value (<=)",
          "type": "search lower than",
          "label in bubble": "true"
        },
        {
          "field": "Beta",
          "label": "Beta (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Z Score",
          "label": "Z Score (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Consequence",
          "label": "Consequence",
          "type": "dropdown",
          "label in bubble": "true"
        }
      ],
      "filter width": "sm",
      "visualizer": {
        "star key": "Variant ID",
        "zoom": "true",
        "type": "region plot",
        "x axis field": "Position",
        "y axis field": "-log10(P-Value)",
        "render by": "Variant ID",
        "y axis label": "-Log10(p-value)",
        "x axis label": "Chromosome",
        "hover content": [
          "P-Value",
          "Beta"
        ],
        "height": 120,
        "plot margin": {
          "left": 200,
          "right": 200,
          "top": 30,
          "bottom": 100,
          "bump": 10
        },
        "ld server": {
          "pos": "Position",
          "ref": "ref",
          "alt": "alt",
          "ref variant field": "Variant ID",
          "populations field": "P-Value",
          "populations type": "fixed",
          "fixed population": "ALL",
          "populations": {
            "ALL": "ALL"
          }
        },
        "genes track": {
          "input type": "dynamic",
          "dynamic parameter": "region"
        },
        "input type": "dynamic",
        "dynamic parameter": "region",
        "if combine y axis field": {
          "type": "average",
          "field": "-log10(P-Value)"
        }
      }
    },
    {
      "section id": "credible_variants",
      "header": "Credible Variants",
      "display":"false",
      "data point": {
        "type": "bioindex",
        "url": "https://giant.hugeampkpnbi.org/api/bio/",
        "index": "credible-variants",
        "parameters": [
          "phenotype",
          "ancestry",
          "csid"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "data convert": [
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "raw",
            "field name": "CV Variant ID",
            "raw field": "Variant ID"
          },
          {
            "type": "join multi",
            "field name": "Ref/Alt",
            "fields to join": [
              "reference",
              "alt"
            ],
            "join by": [
              "/"
            ]
          },
          {
            "type": "raw",
            "field name": "PPO",
            "raw field": "posteriorProbability"
          },
          {
            "type": "raw",
            "field name": "CS ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "EAF",
            "raw field": "eaf"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "pmid"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          }
        ],
        "top rows": [
          "Variant ID",
          "PPO",
          "CS ID",
          "Dataset",
          "EAF",
          "Method",
          "Position",
          "PMID"
        ],
        "locus field": "CS region",
        "star column": "Variant ID",
        "column formatting": {
          "PPO": {
            "type": [
              "scientific notation"
            ]
          }
        }
      },
      "filters unused": [
        {
          "field": "PPO",
          "label": "PPO(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "EAF",
          "label": "EAF(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Dataset",
          "label": "Dataset",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Method",
          "label": "Method",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "PMID",
          "label": "PMID",
          "type": "checkbox",
          "label in bubble": "true"
        }
      ]
    },
    {
      "section id": "page_summary",
      "header": "Variants in region filtered by credible variants in $csid",
      "is summary section": "true",
      "auto summarize": true,
      "sections": {
        "primary section": "associations",
        "sub sections": [
          {
            "section": "credible_variants",
            "label": "Credible Variants in Region",
            "actions": [
              {
                "action": "filter",
                "filter field": "CV Variant ID",
                "target field": "Variant ID",
                "type": "search"
              },
              {
                "action": "add top columns",
                "columns": [
                  {
                    "column": "PPO",
                    "key field": "CV Variant ID",
                    "if multiple values": "pick greater"
                  }
                ]
              },
              {
                "action": "add features",
                "feature": "CS ID",
                "key field": "CV Variant ID",
                "columns": [
                  "CS ID",
                  "PPO",
                  "Dataset",
                  "EAF",
                  "Method",
                  "Position"
                ],
                "if multiple values": "add"
              }
            ]
          }
        ]
      }
    }
  ]
}
